cd /tmp/neutrino-fast-live-b4eG5i/parallel_analysis/fast_dag/1 && node -e '
const fs=require("fs");
const regions=["north","south","east","west"];
const expected={north:{count:10,units:90,weighted:167},south:{count:10,units:94,weighted:171},east:{count:10,units:98,weighted:209},west:{count:10,units:85,weighted:145}};
const out={regions:{},grand_units:0,grand_weighted:0};
let ok=true;
for(const r of regions){
  const raw=fs.readFileSync(r+".json","utf8");
  const data=JSON.parse(raw);
  if(!Array.isArray(data)) throw new Error(r+": not an array");
  const ids=data.map(d=>d.id);
  const problems=[];
  data.forEach((d,i)=>{
    for(const k of ["id","units","weight"]) if(!Number.isInteger(d[k])) problems.push(`${r}[${i}].${k} not integer: ${JSON.stringify(d[k])}`);
    if(Object.keys(d).length!==3) problems.push(`${r}[${i}] unexpected keys: ${Object.keys(d).join(",")}`);
  });
  const count=data.length;
  const units=data.reduce((a,d)=>a+d.units,0);
  const weighted=data.reduce((a,d)=>a+d.units*d.weight,0);
  const dupes=ids.filter((v,i)=>ids.indexOf(v)!==i);
  const expectIds=Array.from({length:count},(_,i)=>i+1);
  const idsContiguous=JSON.stringify(ids)===JSON.stringify(expectIds);
  const e=expected[r];
  const match=e.count===count&&e.units===units&&e.weighted===weighted;
  if(!match||problems.length||dupes.length||!idsContiguous) ok=false;
  out.regions[r]={count,units,weighted};
  out.grand_units+=units; out.grand_weighted+=weighted;
  console.log(`${r}: count=${count} units=${units} weighted=${weighted} ids=${ids.join(",")} contiguous=${idsContiguous} dupes=${dupes.length} problems=${problems.length} inspectorMatch=${match} (inspector count=${e.count},units=${e.units},weighted=${e.weighted})`);
  if(problems.length) console.log("  problems:",problems);
}
console.log("grand_units="+out.grand_units,"grand_weighted="+out.grand_weighted);
console.log("ALL_INSPECTOR_VALUES_MATCH_AND_SOURCE_COMPLETE="+ok);
fs.writeFileSync("answer.json",JSON.stringify(out,null,2)+"\n");
console.log("wrote answer.json");
'

