node -e '
const fs=require("fs");
const insp={north:[10,90,167],south:[10,94,171],east:[10,98,209],west:[10,85,145]};
const out={};let all=true;
for(const r of ["north","south","east","west"]){
  const raw=fs.readFileSync(r+".json","utf8");
  const a=JSON.parse(raw);
  const okArr=Array.isArray(a);
  const keys=a.every(o=>Object.keys(o).sort().join(",")==="id,units,weight");
  const ints=a.every(o=>[o.id,o.units,o.weight].every(v=>Number.isInteger(v)));
  const ids=a.map(o=>o.id);
  const contiguous=ids.every((v,i)=>v===i+1);
  const dupes=ids.length-new Set(ids).size;
  const count=a.length;
  const units=a.reduce((s,o)=>s+o.units,0);
  const weighted=a.reduce((s,o)=>s+o.units*o.weight,0);
  const m=count===insp[r][0]&&units===insp[r][1]&&weighted===insp[r][2];
  out[r]={count,units,weighted};
  if(!(okArr&&keys&&ints&&contiguous&&dupes===0&&m))all=false;
  console.log(r,"count="+count,"units="+units,"weighted="+weighted,"inspector="+insp[r].join("/"),"match="+m,"bytes="+Buffer.byteLength(raw),"arr="+okArr,"keys="+keys,"ints="+ints,"ids1..n="+contiguous,"dupes="+dupes,"records="+a.length);
}
const ans=JSON.parse(fs.readFileSync("answer.json","utf8"));
const topKeys=Object.keys(ans).sort().join(",")==="grand_units,grand_weighted,regions";
const regKeys=Object.keys(ans.regions).sort().join(",")==="east,north,south,west";
let entryOk=true;
for(const r of ["north","south","east","west"]){const e=ans.regions[r];const k=Object.keys(e).sort().join(",")==="count,units,weighted";const v=e.count===out[r].count&&e.units===out[r].units&&e.weighted===out[r].weighted;if(!k||!v){entryOk=false;console.log("MISMATCH",r,JSON.stringify(e),JSON.stringify(out[r]));}}
const gu=Object.values(ans.regions).reduce((s,e)=>s+e.units,0);
const gw=Object.values(ans.regions).reduce((s,e)=>s+e.weighted,0);
const gt=ans.grand_units===gu&&ans.grand_weighted===gw&&ans.grand_units===367&&ans.grand_weighted===692;
console.log("answer topKeys="+topKeys,"regKeys="+regKeys,"entriesMatch="+entryOk,"sumUnits="+gu,"sumWeighted="+gw,"grandConsistent="+gt);
console.log("VERIFY_ALL="+(all&&topKeys&&regKeys&&entryOk&&gt));
'

